import{_ as a,o,c as r,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Welcome Back & Remarks - Enrico Bocchi, Ceph Technical Lead, CERN","description":"","frontmatter":{"title":"Welcome Back & Remarks - Enrico Bocchi, Ceph Technical Lead, CERN","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["Ceph","Distributed Storage","Storage Solutions","CERN","Data Management"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Welcome_Back_Remarks_-_Enrico_Bocchi_Ceph_Technical_Lead_CERN.md","filePath":"posts/2025/Welcome_Back_Remarks_-_Enrico_Bocchi_Ceph_Technical_Lead_CERN.md","lastUpdated":1780459816000}'),n={name:"posts/2025/Welcome_Back_Remarks_-_Enrico_Bocchi_Ceph_Technical_Lead_CERN.md"};function i(l,e,s,c,_,h){return o(),r("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>: Ceph Day 第二天的开场致辞及活动介绍<br><strong>会议时间</strong>: 当天上午<br><strong>主持人</strong>: Enrico（CERN存储团队成员）</p><h4 id="_1-开场致辞" tabindex="-1">1. <strong>开场致辞</strong> <a class="header-anchor" href="#_1-开场致辞" aria-label="Permalink to &quot;1. **开场致辞**&quot;">​</a></h4><ul><li><strong>主持人自我介绍</strong>: Enrico 是 CERN 存储团队的一员，负责 SEF（存储工程部门）的运营。</li><li><strong>感谢赞助商</strong>: 感谢 Platinum 赞助商 Bloomberg Engineering 和 IBM，Gold 赞助商 clo，以及 Silver 赞助商 42on 和 Canonical。鼓励与会者参观赞助商展示区（位于 Auditorium A）。</li><li><strong>感谢 CERN 团队</strong>: 特别感谢 CERN 的 SEF 团队、存储组、管理团队、科学网关团队等，感谢他们的辛勤工作，使得此次活动得以顺利进行。</li></ul><h4 id="_2-cern-存储解决方案介绍" tabindex="-1">2. <strong>CERN 存储解决方案介绍</strong> <a class="header-anchor" href="#_2-cern-存储解决方案介绍" aria-label="Permalink to &quot;2. **CERN 存储解决方案介绍**&quot;">​</a></h4><ul><li><strong>Ceph 在 CERN 的角色</strong>: Ceph 是 CERN 存储的核心解决方案，支持其他可靠存储服务的构建，并为 CERN 社区提供基础设施即服务（IaaS）。</li><li><strong>其他存储服务</strong>: CERN 还提供多样化的科学数据管理工具，包括超大规模磁盘和磁带解决方案、数据移动器、科学数据管理平台、软件分发网络、个人数据管理服务，以及基于云的同步和共享服务。</li><li><strong>CERN Open Lab</strong>: 该部门专注于与外部公司和研究机构建立合作关系，推动技术进步并共同开发创新解决方案。</li><li><strong>未来活动预告</strong>: 包括 Open Lab 技术研讨会、存储技术周（Tech Week Storage）和 CS3 研讨会（计划于明年第一季度举行），欢迎感兴趣的与会者参与。</li></ul><h4 id="_3-会议规则与行为准则" tabindex="-1">3. <strong>会议规则与行为准则</strong> <a class="header-anchor" href="#_3-会议规则与行为准则" aria-label="Permalink to &quot;3. **会议规则与行为准则**&quot;">​</a></h4><ul><li><strong>行为准则</strong>: 请与会者扫描二维码，阅读并遵守会议的行为准则，确保每个人都能感受到欢迎和尊重。</li></ul><h4 id="_4-当日议程" tabindex="-1">4. <strong>当日议程</strong> <a class="header-anchor" href="#_4-当日议程" aria-label="Permalink to &quot;4. **当日议程**&quot;">​</a></h4><ul><li><strong>首场主题演讲</strong>: 由 Ceph 基金会董事会成员共同主持，首先由 Matthew（Bloomberg 存储工程负责人）发表演讲。</li></ul><p><strong>后续行动计划</strong>:</p><ul><li>与会者应参观赞助商展示区，与公司代表直接交流。</li><li>关注 CERN 未来的技术活动，特别是 Open Lab 技术研讨会、存储技术周和 CS3 研讨会。</li><li>遵守会议的行为准则，确保会议的包容性和友好氛围。</li></ul><p><strong>会议结束</strong></p>',13)])])}const p=a(n,[["render",i]]);export{d as __pageData,p as default};
